    'edit_items_por' => 'Edit Items: You can modify the quantities of items to return. Available quantity shows how much can still be returned.',
    'return_quantity_edit_por' => 'Return Quantity: Adjust the quantity for each item. You cannot return more than the available quantity.',
    'status_edit_por' => 'Status: Change the status to "Completed" to process the return, or "Canceled" to reject it. Once Completed or Canceled, edits are no longer allowed.',
